#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re


def report_sort_key(filename: str) -> tuple:
    """Extract numeric part from filename for natural ordering."""
    match = re.search(r'(\d+)', filename)
    return (int(match.group(1)) if match else 0, filename)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'reports')
    try:
        files = [f for f in os.listdir(reports_dir)
                 if os.path.isfile(os.path.join(reports_dir, f))]
    except FileNotFoundError:
        print("Error: reports/ directory not found.")
        return

    files.sort(key=report_sort_key)
    for f in files:
        print(f)


if __name__ == '__main__':
    main()

