#!/usr/bin/env python3
"""Rotate entries in app.log older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_ts(line: str) -> datetime | None:
    """Try to parse a YYYY-MM-DD HH:MM:SS timestamp from the start of line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    with open("app.log") as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped:
            continue
        ts = parse_ts(stripped)
        if ts is not None and ts < cutoff:
            archive.append(stripped)
        else:
            keep.append(stripped)

    # Append to archive.log
    if archive:
        with open("archive.log", "a") as f:
            for entry in archive:
                f.write(entry + "\n")

    # Rewrite app.log
    with open("app.log", "w") as f:
        for entry in keep:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

