import sys
import os
from datetime import datetime, timezone

def parse_timestamp(line):
    """Parse the YYYY-MM-DD HH:MM:SS prefix from a log line, return datetime or None."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_ts = as_of - 7 * 86400  # strictly older than 7 days before AS_OF

    log_path = "app.log"
    archive_path = "archive.log"

    if not os.path.exists(log_path):
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    kept = []
    archived = []

    with open(log_path, "r") as f:
        for line in f:
            if not line.strip():
                continue
            dt = parse_timestamp(line)
            if dt is None:
                # If we can't parse, keep it (fallback)
                kept.append(line)
            else:
                entry_ts = int(dt.timestamp())
                if entry_ts < cutoff_ts:
                    archived.append(line)
